import 'package:firebase_core/firebase_core.dart' show FirebaseOptions;
import 'package:flutter/foundation.dart' show defaultTargetPlatform, kIsWeb, TargetPlatform;

/// Replace the placeholder values below with the configuration generated by
/// `flutterfire configure`. Do not commit production secrets to public repos.
class DefaultFirebaseOptions {
  DefaultFirebaseOptions._();

  static const String _placeholder = 'REPLACE_ME';
  static bool get isConfigured =>
    android.apiKey != _placeholder &&
    android.appId != _placeholder &&
    android.projectId != _placeholder;

  static FirebaseOptions get currentPlatform {
    if (!isConfigured) {
      throw StateError(
        'Firebase is not configured. Run `flutterfire configure` and replace '
        'lib/firebase_options.dart with the generated file.',
      );
    }
    if (kIsWeb) return web;
    switch (defaultTargetPlatform) {
      case TargetPlatform.android:
        return android;
      case TargetPlatform.iOS:
        return ios;
      case TargetPlatform.macOS:
        return macos;
      case TargetPlatform.windows:
        return windows;
      case TargetPlatform.linux:
        return linux;
      case TargetPlatform.fuchsia:
        throw UnsupportedError('Firebase is not configured for Fuchsia.');
    }
  }

  // These are intentionally placeholders, not usable Firebase credentials.
  static const FirebaseOptions web = FirebaseOptions(
    apiKey: _placeholder, appId: _placeholder,
    messagingSenderId: _placeholder, projectId: _placeholder,
  );

  static const FirebaseOptions android = FirebaseOptions(
    apiKey: 'AIzaSyDROcoeP0X2qHIP4h23sSWqU8XPeEbyWiY',
    appId: '1:742119978110:android:375f29f050013d1e33142f',
    messagingSenderId: '742119978110',
    projectId: 'elsewhere-da0e3',
    storageBucket: 'elsewhere-da0e3.firebasestorage.app',
  );
  static const FirebaseOptions ios = FirebaseOptions(
    apiKey: _placeholder, appId: _placeholder,
    messagingSenderId: _placeholder, projectId: _placeholder,
    iosBundleId: 'com.example.elsewhere',
  );
  static const FirebaseOptions macos = FirebaseOptions(
    apiKey: _placeholder, appId: _placeholder,
    messagingSenderId: _placeholder, projectId: _placeholder,
    iosBundleId: 'com.example.elsewhere',
  );
  static const FirebaseOptions windows = FirebaseOptions(
    apiKey: _placeholder, appId: _placeholder,
    messagingSenderId: _placeholder, projectId: _placeholder,
  );
  static const FirebaseOptions linux = FirebaseOptions(
    apiKey: _placeholder, appId: _placeholder,
    messagingSenderId: _placeholder, projectId: _placeholder,
  );
}
